diff --git a/debian/changelog b/debian/changelog
index 295102a..ddfa107 100644
--- a/debian/changelog
+++ b/debian/changelog
@@ -1,3 +1,10 @@
+openssh (1:9.6p1-3ubuntu13.21) noble; urgency=medium
+
+  * Add sntrup761x25519-sha512 key exchange (LP: #2120496)
+  * Add mlkem768x25519-sha256 key exchange (LP: #2120496)
+
+ -- Artur Martins <artur.martins@canonical.com>  Wed, 14 Oct 2026 14:20:00 +0100
+
 openssh (1:9.6p1-3ubuntu13.20) noble-security; urgency=medium

   * SECURITY UPDATE: sftp directory traversal
diff --git a/debian/patches/mlkem768x25519-sha256.patch b/debian/patches/mlkem768x25519-sha256.patch
new file mode 100644
index 0000000..475d9a7
--- /dev/null
+++ b/debian/patches/mlkem768x25519-sha256.patch
@@ -0,0 +1,28646 @@
+Origin: backport, https://code.launchpad.net/~git-ubuntu-import/ubuntu/+source/openssh/+git/openssh/+ref/applied/ubuntu/questing-devel
+Subject: [PATCH] Add mlkem768x25519-sha256 key exchange
+
+Add the mlkem768x25519-sha256 (ML-KEM 768 with X25519) hybrid key exchange
+method, including the libcrux ML-KEM/ML-DSA implementation and unit tests.
+Register the mlkem768x25519-sha256 server handler in the preauth key
+exchange setup in sshd.c.
+
+Bug-Ubuntu: https://bugs.launchpad.net/bugs/2120496
+Forwarded: no
+---
+
+--- openssh-9.6p1.orig/Makefile.in
++++ openssh-9.6p1/Makefile.in
+@@ -110,7 +110,8 @@ LIBSSH_OBJS=${LIBOPENSSH_OBJS} \
+ 	hmac.o ed25519.o hash.o \
+ 	kex.o kexdh.o kexgex.o kexecdh.o kexc25519.o \
+ 	kexgexc.o kexgexs.o \
+-	kexsntrup761x25519.o sntrup761.o kexgen.o \
++	kexsntrup761x25519.o sntrup761.o kexmlkem768x25519.o \
++	libcrux-mlkem-mldsa.o kexgen.o \
+ 	kexgssc.o \
+ 	sftp-realpath.o platform-pledge.o platform-tracing.o platform-misc.o \
+ 	sshbuf-io.o
+@@ -292,6 +293,8 @@ clean:	regressclean
+ 	rm -f regress/unittests/bitmap/test_bitmap$(EXEEXT)
+ 	rm -f regress/unittests/conversion/*.o
+ 	rm -f regress/unittests/conversion/test_conversion$(EXEEXT)
++	rm -f regress/unittests/crypto/*.o
++	rm -f regress/unittests/crypto/test_crypto$(EXEEXT)
+ 	rm -f regress/unittests/hostkeys/*.o
+ 	rm -f regress/unittests/hostkeys/test_hostkeys$(EXEEXT)
+ 	rm -f regress/unittests/kex/*.o
+@@ -329,6 +332,8 @@ distclean:	regressclean
+ 	rm -f regress/unittests/bitmap/test_bitmap
+ 	rm -f regress/unittests/conversion/*.o
+ 	rm -f regress/unittests/conversion/test_conversion
++	rm -f regress/unittests/crypto/*.o
++	rm -f regress/unittests/crypto/test_crypto
+ 	rm -f regress/unittests/hostkeys/*.o
+ 	rm -f regress/unittests/hostkeys/test_hostkeys
+ 	rm -f regress/unittests/kex/*.o
+@@ -517,6 +522,7 @@ regress-prep:
+ 	$(MKDIR_P) `pwd`/regress/unittests/authopt
+ 	$(MKDIR_P) `pwd`/regress/unittests/bitmap
+ 	$(MKDIR_P) `pwd`/regress/unittests/conversion
++	$(MKDIR_P) `pwd`/regress/unittests/crypto
+ 	$(MKDIR_P) `pwd`/regress/unittests/hostkeys
+ 	$(MKDIR_P) `pwd`/regress/unittests/kex
+ 	$(MKDIR_P) `pwd`/regress/unittests/match
+@@ -626,6 +632,17 @@ regress/unittests/authopt/test_authopt$(
+ 	    regress/unittests/test_helper/libtest_helper.a \
+ 	    -lssh -lopenbsd-compat -lssh -lopenbsd-compat $(TESTLIBS)
+ 
++UNITTESTS_TEST_CRYPTO_OBJS=\
++	regress/unittests/crypto/tests.o \
++	regress/unittests/crypto/test_mlkem.o
++
++regress/unittests/crypto/test_crypto$(EXEEXT): \
++    ${UNITTESTS_TEST_CRYPTO_OBJS} \
++    regress/unittests/test_helper/libtest_helper.a libssh.a
++	$(LD) -o $@ $(LDFLAGS) $(UNITTESTS_TEST_CRYPTO_OBJS) \
++	    regress/unittests/test_helper/libtest_helper.a \
++	    -lssh -lopenbsd-compat -lssh -lopenbsd-compat $(TESTLIBS)
++
+ UNITTESTS_TEST_CONVERSION_OBJS=\
+ 	regress/unittests/conversion/tests.o
+ 
+@@ -725,6 +742,7 @@ regress-unit-binaries: regress-prep $(RE
+ 	regress/unittests/authopt/test_authopt$(EXEEXT) \
+ 	regress/unittests/bitmap/test_bitmap$(EXEEXT) \
+ 	regress/unittests/conversion/test_conversion$(EXEEXT) \
++	regress/unittests/crypto/test_crypto$(EXEEXT) \
+ 	regress/unittests/hostkeys/test_hostkeys$(EXEEXT) \
+ 	regress/unittests/kex/test_kex$(EXEEXT) \
+ 	regress/unittests/match/test_match$(EXEEXT) \
+--- openssh-9.6p1.orig/crypto_api.h
++++ openssh-9.6p1/crypto_api.h
+@@ -53,4 +53,61 @@ int	crypto_kem_sntrup761_dec(unsigned ch
+     const unsigned char *cstr, const unsigned char *sk);
+ int	crypto_kem_sntrup761_keypair(unsigned char *pk, unsigned char *sk);
+ 
++/* ML-KEM-768 */
++#define crypto_kem_mlkem768_PUBLICKEYBYTES 1184
++#define crypto_kem_mlkem768_SECRETKEYBYTES 2400
++#define crypto_kem_mlkem768_CIPHERTEXTBYTES 1088
++#define crypto_kem_mlkem768_BYTES 32
++#define crypto_kem_mlkem768_ENCSEEDBYTES 32
++#define crypto_kem_mlkem768_KEYPAIRSEEDBYTES 64
++
++/* Aliases for MLKEM768 */
++#define MLKEM768_PUBLICKEYBYTES crypto_kem_mlkem768_PUBLICKEYBYTES
++#define MLKEM768_SECRETKEYBYTES crypto_kem_mlkem768_SECRETKEYBYTES
++#define MLKEM768_CIPHERTEXTBYTES crypto_kem_mlkem768_CIPHERTEXTBYTES
++#define MLKEM768_BYTES crypto_kem_mlkem768_BYTES
++
++int crypto_kem_mlkem768_keypair(uint8_t pk[crypto_kem_mlkem768_PUBLICKEYBYTES],
++    uint8_t sk[crypto_kem_mlkem768_SECRETKEYBYTES]);
++int crypto_kem_mlkem768_enc(uint8_t ct[crypto_kem_mlkem768_CIPHERTEXTBYTES],
++    uint8_t shared_secret[crypto_kem_mlkem768_BYTES],
++    const uint8_t pk[crypto_kem_mlkem768_PUBLICKEYBYTES]);
++int crypto_kem_mlkem768_dec(uint8_t shared_secret[crypto_kem_mlkem768_BYTES],
++    const uint8_t ct[crypto_kem_mlkem768_CIPHERTEXTBYTES],
++    const uint8_t sk[crypto_kem_mlkem768_SECRETKEYBYTES]);
++int crypto_kem_mlkem768_keypair_seeded(uint8_t pk[crypto_kem_mlkem768_PUBLICKEYBYTES],
++    uint8_t sk[crypto_kem_mlkem768_SECRETKEYBYTES], const uint8_t seed[64]);
++int crypto_kem_mlkem768_enc_seeded(uint8_t ct[crypto_kem_mlkem768_CIPHERTEXTBYTES],
++    uint8_t shared_secret[crypto_kem_mlkem768_BYTES],
++    const uint8_t pk[crypto_kem_mlkem768_PUBLICKEYBYTES],
++    const uint8_t seed[32]);
++
++/* ML-DSA-44 */
++#define MLDSA44_PUBLICKEYBYTES 1312
++#define MLDSA44_SECRETKEYBYTES 2560
++#define MLDSA44_SIGBYTES 2420
++#define MLDSA44_SEEDBYTES 32
++
++int crypto_sign_mldsa44_keypair(uint8_t pk[MLDSA44_PUBLICKEYBYTES],
++    uint8_t sk[MLDSA44_SECRETKEYBYTES]);
++int crypto_sign_mldsa44(uint8_t sig[MLDSA44_SIGBYTES],
++    const uint8_t *msg, size_t msglen,
++    const uint8_t *ctx, size_t ctxlen,
++    const uint8_t sk[MLDSA44_SECRETKEYBYTES]);
++int crypto_sign_mldsa44_verify(const uint8_t sig[MLDSA44_SIGBYTES],
++    const uint8_t *msg, size_t msglen,
++    const uint8_t *ctx, size_t ctxlen,
++    const uint8_t pk[MLDSA44_PUBLICKEYBYTES]);
++int crypto_sign_mldsa44_keypair_seeded(uint8_t pk[MLDSA44_PUBLICKEYBYTES],
++    uint8_t sk[MLDSA44_SECRETKEYBYTES], const uint8_t seed[MLDSA44_SEEDBYTES]);
++int crypto_sign_mldsa44_seeded(uint8_t sig[MLDSA44_SIGBYTES],
++    const uint8_t *msg, size_t msglen,
++    const uint8_t *ctx, size_t ctxlen,
++    const uint8_t sk[MLDSA44_SECRETKEYBYTES],
++    const uint8_t seed[MLDSA44_SEEDBYTES]);
++
++/* Utility */
++void sha3_256(uint8_t digest[32], const uint8_t *data, size_t len);
++void sha3_512(uint8_t digest[64], const uint8_t *data, size_t len);
++
+ #endif /* crypto_api_h */
+--- openssh-9.6p1.orig/defines.h
++++ openssh-9.6p1/defines.h
+@@ -947,5 +947,7 @@ struct winsize {
+  */
+ #if defined(VARIABLE_LENGTH_ARRAYS) && defined(VARIABLE_DECLARATION_AFTER_CODE)
+ # define USE_SNTRUP761X25519 1
++/* The ML-KEM768 implementation also uses C89 features */
++# define USE_MLKEM768X25519 1
+ #endif
+ #endif /* _DEFINES_H */
+--- openssh-9.6p1.orig/kex.c
++++ openssh-9.6p1/kex.c
+@@ -123,6 +123,10 @@
+ 	{ KEX_SNTRUP761X25519_SHA512, KEX_KEM_SNTRUP761X25519_SHA512, 0,
+ 	    SSH_DIGEST_SHA512 },
+ #endif
++#ifdef USE_MLKEM768X25519
++	{ KEX_MLKEM768X25519_SHA256, KEX_KEM_MLKEM768X25519_SHA256, 0,
++	    SSH_DIGEST_SHA256 },
++#endif
+ #endif /* HAVE_EVP_SHA256 || !WITH_OPENSSL */
+ 	{ NULL, 0, -1, -1},
+ };
+--- openssh-9.6p1.orig/kex.h
++++ openssh-9.6p1/kex.h
+@@ -64,6 +64,7 @@
+ #define	KEX_CURVE25519_SHA256_OLD	"curve25519-sha256@libssh.org"
+ #define	KEX_SNTRUP761X25519_SHA512	"sntrup761x25519-sha512@openssh.com"
+ #define	KEX_SNTRUP761X25519_SHA512_IANA	"sntrup761x25519-sha512"
++#define	KEX_MLKEM768X25519_SHA256	"mlkem768x25519-sha256"
+ 
+ #define COMP_NONE	0
+ /* pre-auth compression (COMP_ZLIB) is only supported in the client */
+@@ -112,6 +113,7 @@
+ 	KEX_GSS_NISTP256_SHA256,
+ 	KEX_GSS_C25519_SHA256,
+ #endif
++	KEX_KEM_MLKEM768X25519_SHA256,
+ 	KEX_MAX
+ };
+ 
+@@ -196,6 +198,7 @@
+ 	u_char c25519_client_key[CURVE25519_SIZE]; /* 25519 + KEM */
+ 	u_char c25519_client_pubkey[CURVE25519_SIZE]; /* 25519 */
+ 	u_char sntrup761_client_key[crypto_kem_sntrup761_SECRETKEYBYTES]; /* KEM */
++	u_char mlkem768_client_key[crypto_kem_mlkem768_SECRETKEYBYTES]; /* KEM */
+ 	struct sshbuf *client_pub;
+ };
+ 
+@@ -265,6 +268,12 @@
+ int	 kex_kem_sntrup761x25519_dec(struct kex *, const struct sshbuf *,
+     struct sshbuf **);
+ 
++int	 kex_kem_mlkem768x25519_keypair(struct kex *);
++int	 kex_kem_mlkem768x25519_enc(struct kex *, const struct sshbuf *,
++    struct sshbuf **, struct sshbuf **);
++int	 kex_kem_mlkem768x25519_dec(struct kex *, const struct sshbuf *,
++    struct sshbuf **);
++
+ int	 kex_dh_keygen(struct kex *);
+ int	 kex_dh_compute_key(struct kex *, BIGNUM *, struct sshbuf *);
+ 
+--- openssh-9.6p1.orig/kexgen.c
++++ openssh-9.6p1/kexgen.c
+@@ -120,6 +120,9 @@ kex_gen_client(struct ssh *ssh)
+ 	case KEX_KEM_SNTRUP761X25519_SHA512:
+ 		r = kex_kem_sntrup761x25519_keypair(kex);
+ 		break;
++	case KEX_KEM_MLKEM768X25519_SHA256:
++		r = kex_kem_mlkem768x25519_keypair(kex);
++		break;
+ 	default:
+ 		r = SSH_ERR_INVALID_ARGUMENT;
+ 		break;
+@@ -192,6 +195,10 @@ input_kex_gen_reply(int type, u_int32_t
+ 		r = kex_kem_sntrup761x25519_dec(kex, server_blob,
+ 		    &shared_secret);
+ 		break;
++	case KEX_KEM_MLKEM768X25519_SHA256:
++		r = kex_kem_mlkem768x25519_dec(kex, server_blob,
++		    &shared_secret);
++		break;
+ 	default:
+ 		r = SSH_ERR_INVALID_ARGUMENT;
+ 		break;
+@@ -243,6 +250,8 @@ out:
+ 	explicit_bzero(kex->c25519_client_key, sizeof(kex->c25519_client_key));
+ 	explicit_bzero(kex->sntrup761_client_key,
+ 	    sizeof(kex->sntrup761_client_key));
++	explicit_bzero(kex->mlkem768_client_key,
++	    sizeof(kex->mlkem768_client_key));
+ 	sshbuf_free(server_host_key_blob);
+ 	free(signature);
+ 	sshbuf_free(tmp);
+@@ -310,6 +319,10 @@ input_kex_gen_init(int type, u_int32_t s
+ 		r = kex_kem_sntrup761x25519_enc(kex, client_pubkey,
+ 		    &server_pubkey, &shared_secret);
+ 		break;
++	case KEX_KEM_MLKEM768X25519_SHA256:
++		r = kex_kem_mlkem768x25519_enc(kex, client_pubkey,
++		    &server_pubkey, &shared_secret);
++		break;
+ 	default:
+ 		r = SSH_ERR_INVALID_ARGUMENT;
+ 		break;
+--- /dev/null
++++ openssh-9.6p1/kexmlkem768x25519.c
+@@ -0,0 +1,261 @@
++/* $OpenBSD: kexmlkem768x25519.c,v 1.3 2026/06/14 03:59:34 djm Exp $ */
++/*
++ * Copyright (c) 2023 Markus Friedl.  All rights reserved.
++ *
++ * Redistribution and use in source and binary forms, with or without
++ * modification, are permitted provided that the following conditions
++ * are met:
++ * 1. Redistributions of source code must retain the above copyright
++ *    notice, this list of conditions and the following disclaimer.
++ * 2. Redistributions in binary form must reproduce the above copyright
++ *    notice, this list of conditions and the following disclaimer in the
++ *    documentation and/or other materials provided with the distribution.
++ *
++ * THIS SOFTWARE IS PROVIDED BY THE AUTHOR ``AS IS'' AND ANY EXPRESS OR
++ * IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED WARRANTIES
++ * OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE ARE DISCLAIMED.
++ * IN NO EVENT SHALL THE AUTHOR BE LIABLE FOR ANY DIRECT, INDIRECT,
++ * INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL DAMAGES (INCLUDING, BUT
++ * NOT LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR SERVICES; LOSS OF USE,
++ * DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER CAUSED AND ON ANY
++ * THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY, OR TORT
++ * (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE OF
++ * THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.
++ */
++
++#include "includes.h"
++
++#include <sys/types.h>
++
++#include <stdio.h>
++#include <stdint.h>
++#include <stdbool.h>
++#include <string.h>
++#include <signal.h>
++#include <endian.h>
++
++#include "sshkey.h"
++#include "kex.h"
++#include "sshbuf.h"
++#include "digest.h"
++#include "ssherr.h"
++#include "log.h"
++
++#include "crypto_api.h"
++
++#ifdef USE_MLKEM768X25519
++
++int
++kex_kem_mlkem768x25519_keypair(struct kex *kex)
++{
++	struct sshbuf *buf = NULL;
++	u_char *cp = NULL;
++	size_t need;
++	int r = SSH_ERR_INTERNAL_ERROR;
++
++	if ((buf = sshbuf_new()) == NULL)
++		return SSH_ERR_ALLOC_FAIL;
++	need = MLKEM768_PUBLICKEYBYTES + CURVE25519_SIZE;
++	if ((r = sshbuf_reserve(buf, need, &cp)) != 0)
++		goto out;
++	if (crypto_kem_mlkem768_keypair(cp, kex->mlkem768_client_key) != 0) {
++		r = SSH_ERR_INTERNAL_ERROR;
++		goto out;
++	}
++#ifdef DEBUG_KEXECDH
++	dump_digest("client public key mlkem768:", cp,
++	    MLKEM768_PUBLICKEYBYTES);
++#endif
++	cp += MLKEM768_PUBLICKEYBYTES;
++	kexc25519_keygen(kex->c25519_client_key, cp);
++#ifdef DEBUG_KEXECDH
++	dump_digest("client public key c25519:", cp, CURVE25519_SIZE);
++#endif
++	/* success */
++	r = 0;
++	kex->client_pub = buf;
++	buf = NULL;
++ out:
++	sshbuf_free(buf);
++	return r;
++}
++
++int
++kex_kem_mlkem768x25519_enc(struct kex *kex,
++   const struct sshbuf *client_blob, struct sshbuf **server_blobp,
++   struct sshbuf **shared_secretp)
++{
++	struct sshbuf *server_blob = NULL;
++	struct sshbuf *buf = NULL;
++	const u_char *client_pub;
++	u_char server_pub[CURVE25519_SIZE], server_key[CURVE25519_SIZE];
++	u_char hash[SSH_DIGEST_MAX_LENGTH];
++	u_char ct[MLKEM768_CIPHERTEXTBYTES];
++	u_char shared_secret[MLKEM768_BYTES];
++	size_t need;
++	int r = SSH_ERR_INTERNAL_ERROR;
++
++	*server_blobp = NULL;
++	*shared_secretp = NULL;
++
++	/* client_blob contains both KEM and ECDH client pubkeys */
++	need = MLKEM768_PUBLICKEYBYTES + CURVE25519_SIZE;
++	if (sshbuf_len(client_blob) != need) {
++		r = SSH_ERR_SIGNATURE_INVALID;
++		goto out;
++	}
++	client_pub = sshbuf_ptr(client_blob);
++#ifdef DEBUG_KEXECDH
++	dump_digest("client public key mlkem768:", client_pub,
++	    MLKEM768_PUBLICKEYBYTES);
++	dump_digest("client public key 25519:",
++	    client_pub + MLKEM768_PUBLICKEYBYTES,
++	    CURVE25519_SIZE);
++#endif
++
++	/* allocate buffer for concatenation of KEM key and ECDH shared key */
++	/* the buffer will be hashed and the result is the shared secret */
++	if ((buf = sshbuf_new()) == NULL) {
++		r = SSH_ERR_ALLOC_FAIL;
++		goto out;
++	}
++	/* allocate space for encrypted KEM key and ECDH pub key */
++	if ((server_blob = sshbuf_new()) == NULL) {
++		r = SSH_ERR_ALLOC_FAIL;
++		goto out;
++	}
++	/* generate and encrypt KEM key with client key */
++	if (crypto_kem_mlkem768_enc(ct, shared_secret, client_pub) != 0) {
++		r = SSH_ERR_INTERNAL_ERROR;
++		goto out;
++	}
++	/* generate ECDH key pair, store server pubkey after ciphertext */
++	kexc25519_keygen(server_key, server_pub);
++	if ((r = sshbuf_put(buf, shared_secret, sizeof(shared_secret))) != 0 ||
++	    (r = sshbuf_put(server_blob, ct, sizeof(ct))) != 0 ||
++	    (r = sshbuf_put(server_blob, server_pub, sizeof(server_pub))) != 0)
++		goto out;
++	/* append ECDH shared key */
++	client_pub += MLKEM768_PUBLICKEYBYTES;
++	if ((r = kexc25519_shared_key_ext(server_key, client_pub, buf, 1)) < 0)
++		goto out;
++	if ((r = ssh_digest_buffer(kex->hash_alg, buf,
++	    hash, sizeof(hash))) != 0)
++		goto out;
++#ifdef DEBUG_KEXECDH
++	dump_digest("server public key 25519:", server_pub, CURVE25519_SIZE);
++	dump_digest("server cipher text:", ct, sizeof(ct));
++	dump_digest("server kem key:", shared_secret, sizeof(shared_secret));
++	dump_digest("concatenation of KEM key and ECDH shared key:",
++	    sshbuf_ptr(buf), sshbuf_len(buf));
++#endif
++	/* string-encoded hash is resulting shared secret */
++	sshbuf_reset(buf);
++	if ((r = sshbuf_put_string(buf, hash,
++	    ssh_digest_bytes(kex->hash_alg))) != 0)
++		goto out;
++#ifdef DEBUG_KEXECDH
++	dump_digest("encoded shared secret:", sshbuf_ptr(buf), sshbuf_len(buf));
++#endif
++	/* success */
++	r = 0;
++	*server_blobp = server_blob;
++	*shared_secretp = buf;
++	server_blob = NULL;
++	buf = NULL;
++ out:
++	explicit_bzero(hash, sizeof(hash));
++	explicit_bzero(server_key, sizeof(server_key));
++	explicit_bzero(shared_secret, sizeof(shared_secret));
++	sshbuf_free(server_blob);
++	sshbuf_free(buf);
++	return r;
++}
++
++int
++kex_kem_mlkem768x25519_dec(struct kex *kex,
++    const struct sshbuf *server_blob, struct sshbuf **shared_secretp)
++{
++	struct sshbuf *buf = NULL;
++	u_char shared_secret[MLKEM768_BYTES];
++	const u_char *ciphertext, *server_pub;
++	u_char hash[SSH_DIGEST_MAX_LENGTH];
++	size_t need;
++	int r;
++
++	*shared_secretp = NULL;
++
++	need = MLKEM768_CIPHERTEXTBYTES + CURVE25519_SIZE;
++	if (sshbuf_len(server_blob) != need) {
++		r = SSH_ERR_SIGNATURE_INVALID;
++		goto out;
++	}
++	ciphertext = sshbuf_ptr(server_blob);
++	server_pub = ciphertext + MLKEM768_CIPHERTEXTBYTES;
++	/* hash concatenation of KEM key and ECDH shared key */
++	if ((buf = sshbuf_new()) == NULL) {
++		r = SSH_ERR_ALLOC_FAIL;
++		goto out;
++	}
++#ifdef DEBUG_KEXECDH
++	dump_digest("server cipher text:", ciphertext,
++	    MLKEM768_CIPHERTEXTBYTES);
++	dump_digest("server public key c25519:", server_pub, CURVE25519_SIZE);
++#endif
++	if (crypto_kem_mlkem768_dec(shared_secret, ciphertext,
++	    kex->mlkem768_client_key) != 0) {
++		r = SSH_ERR_INTERNAL_ERROR;
++		goto out;
++	}
++	if ((r = sshbuf_put(buf, shared_secret, sizeof(shared_secret))) != 0)
++		goto out;
++	if ((r = kexc25519_shared_key_ext(kex->c25519_client_key, server_pub,
++	    buf, 1)) < 0)
++		goto out;
++	if ((r = ssh_digest_buffer(kex->hash_alg, buf,
++	    hash, sizeof(hash))) != 0)
++		goto out;
++#ifdef DEBUG_KEXECDH
++	dump_digest("client kem key:", shared_secret, sizeof(shared_secret));
++	dump_digest("concatenation of KEM key and ECDH shared key:",
